export const MOVIES: Movie[] = RAW;

let _moviesCache: Movie[] | null = null;
function movies(): Movie[] {
  if (!_moviesCache) _moviesCache = MOVIES;
  return _moviesCache;
}

export function getAllMovies(): Movie[] { return movies(); }

export function getFeaturedMovies(): Movie[] {
  // Микс: 3 классики (топ рейтинг) + 3 новинки (последние годы) для разнообразия hero
  const classics = movies()
    .filter((m) => m.backdropUrl || m.featured)
    .sort((a, b) => b.rating - a.rating)
    .slice(0, 3);
  const recent = movies()
    .filter((m) => m.year >= 2018 && m.rating >= 7.5 && !classics.find((c) => c.id === m.id))
    .sort((a, b) => b.year - a.year || b.rating - a.rating)
    .slice(0, 3);
  const mixed = [...classics, ...recent];
  return mixed.length >= 4 ? mixed : movies().filter((m) => m.backdropUrl).slice(0, 6);
}

export function getTrendingMovies(): Movie[] {
  return [...movies()].sort((a, b) => b.views - a.views).slice(0, 14);
}

export function getNewReleases(): Movie[] {
  return [...movies()].sort((a, b) => b.year - a.year).slice(0, 14);
}

export function getMovieById(id: string): Movie | undefined {
  return movies().find((m) => m.id === id);
}

export function getMovieByKinopoiskId(kpId: number): Movie | undefined {
  return movies().find((m) => m.kinopoiskId === kpId);
}

export function searchMovies(query: string): Movie[] {
  const q = query.trim().toLowerCase();
  if (!q) return [];
  const words = q.split(/\s+/).filter((w) => w.length >= 2);
  if (words.length === 0) return [];

  return movies()
    .map((m) => {
      const haystack = [m.title, m.originalTitle, m.director, m.description, m.genres.join(" "), m.cast.join(" "), String(m.year), String(m.kinopoiskId)].join(" ").toLowerCase();
      // Подсчёт очков: сколько слов из запроса найдены
      let score = 0;
      // Точное совпадение названия — высший приоритет
      if (m.title.toLowerCase() === q || m.originalTitle.toLowerCase() === q) score += 100;
      // Частичное совпадение названия
      if (m.title.toLowerCase().includes(q) || m.originalTitle.toLowerCase().includes(q)) score += 50;
      // Каждое слово из запроса
      for (const w of words) {
        if (haystack.includes(w)) score += 10;
        if (m.title.toLowerCase().includes(w) || m.originalTitle.toLowerCase().includes(w)) score += 5;
      }
      return { m, score };
    })
    .filter((x) => x.score > 0)
    .sort((a, b) => b.score - a.score || b.m.rating - a.m.rating)
    .slice(0, 30)
    .map((x) => x.m);
}

export function getMoviesByGenre(genre: string): Movie[] {
  if (!genre || genre === "Все") return movies();
  return movies().filter((m) => m.genres.includes(genre));
}

export function getAllGenres(): Genre[] {
  const counts = new Map<string, number>();
  for (const m of movies()) {
    for (const g of m.genres) counts.set(g, (counts.get(g) ?? 0) + 1);
  }
  return [{ name: "Все", count: movies().length }, ...Array.from(counts.entries()).map(([name, count]) => ({ name, count })).sort((a, b) => b.count - a.count)];
}

export function getSimilarMovies(id: string, limit = 6): Movie[] {
  const current = getMovieById(id);
  if (!current) return [];
  return movies()
    .filter((m) => m.id !== id)
    .map((m) => ({ m, score: m.genres.filter((g) => current.genres.includes(g)).length }))
    .sort((a, b) => b.score - a.score || b.m.views - a.m.views)
    .slice(0, limit)
    .map((x) => x.m);
}

// ----- Расширенная фильтрация -----

export interface MovieFilters {
  genre?: string;       // "Все" или конкретный жанр
  country?: string;    // "Все" или конкретная страна
  yearFrom?: number;    // минимальный год
  yearTo?: number;      // максимальный год
  ratingFrom?: number;   // минимальный рейтинг (0-10)
  ratingTo?: number;     // максимальный рейтинг (0-10)
  sort?: SortOption;    // сортировка
}

export type SortOption =
  | "rating-desc"    // по рейтингу ↓
  | "rating-asc"     // по рейтингу ↑
  | "year-desc"      // по новизне ↓
  | "year-asc"       // по году ↑
  | "views-desc"     // по популярности ↓
  | "title-asc";     // по названию А-Я

export function filterMovies(filters: MovieFilters): Movie[] {
  let result = movies().filter((m) => {
    // Жанр
    if (filters.genre && filters.genre !== "Все" && !m.genres.includes(filters.genre)) {
      return false;
    }
    // Страна
    if (filters.country && filters.country !== "Все" && !m.countries.includes(filters.country)) {
      return false;
    }
    // Год: диапазон
    if (filters.yearFrom && m.year < filters.yearFrom) return false;
    if (filters.yearTo && m.year > filters.yearTo) return false;
    // Рейтинг: диапазон
    if (filters.ratingFrom && m.rating < filters.ratingFrom) return false;
    if (filters.ratingTo && m.rating > filters.ratingTo) return false;
    return true;
  });

  // Сортировка
  const sort = filters.sort ?? "rating-desc";
  result = [...result];
  switch (sort) {
    case "rating-desc": result.sort((a, b) => b.rating - a.rating); break;
    case "rating-asc": result.sort((a, b) => a.rating - b.rating); break;
    case "year-desc": result.sort((a, b) => b.year - a.year); break;
    case "year-asc": result.sort((a, b) => a.year - b.year); break;
    case "views-desc": result.sort((a, b) => b.views - a.views); break;
    case "title-asc": result.sort((a, b) => a.title.localeCompare(b.title, "ru")); break;
  }
  return result;
}

export function getAllCountries(): Genre[] {
  const counts = new Map<string, number>();
  for (const m of movies()) {
    for (const c of m.countries) counts.set(c, (counts.get(c) ?? 0) + 1);
  }
  return [
    { name: "Все", count: movies().length },
    ...Array.from(counts.entries())
      .map(([name, count]) => ({ name, count }))
      .sort((a, b) => b.count - a.count),
  ];
}

export function getYearRange(): { min: number; max: number } {
  const years = movies().map((m) => m.year).filter(Boolean);
  if (years.length === 0) return { min: 1960, max: 2026 };
  return { min: Math.min(...years), max: Math.max(...years) };
}

